using System;
using System.Linq;
using System.Collections.Generic;
using System.Reflection;
using LastRail.Battle;
using Newtonsoft.Json.Linq;
using NUnit.Framework;
namespace LastRail.Tests.EditMode {
 public sealed class CombatVitalsModelConnectionTests {
  static BasicCombatActor Actor(string id,bool enemy,bool train,int slot,string device=null)=>new BasicCombatActor(id,enemy,train,false,slot,1000,enemy?100:0,0,100,1,0,enemy?BasicCombatTarget.Train:BasicCombatTarget.EnemyAny,4000,device==null?null:new BasicCombatTiming(0,0,device,false,null));
  static BasicCombatSimulation Fresh()=>new BasicCombatSimulation("TEST_ONLY_approved_vitals",500000,1u,new[]{Actor("train",false,true,0),Actor("gun-a",false,false,1,"Gun"),Actor("gun-b",false,false,2,"Gun")},new[]{new[]{Actor("enemy",true,false,0)}},true);
  static JToken HpRow(BasicCombatSimulation s,string id)=>((JArray)s.ReadHudState()["actors"]).Single(a=>(string)a["id"]==id);
  static void ApplyBatch(object owner,IReadOnlyDictionary<string,int> values){var method=owner.GetType().GetMethod("ApplyResolvedMaxHpBatch");Assert.That(method,Is.Not.Null,"Missing atomic final HP batch boundary");try{method.Invoke(owner,new object[]{values});}catch(TargetInvocationException ex){throw ex.InnerException??ex;}}
  [Test] public void InvalidLaterFinalHpCannotPartiallyChangeEarlierTarget(){var s=Fresh();var before=s.CaptureLocalState();Assert.Throws<ArgumentOutOfRangeException>(()=>ApplyBatch(s,new Dictionary<string,int>{{"gun-a",1500},{"gun-b",0}}));Assert.That(s.CaptureLocalState(),Is.EqualTo(before));Assert.Throws<KeyNotFoundException>(()=>ApplyBatch(s,new Dictionary<string,int>{{"gun-a",1500},{"missing",1000}}));Assert.That(s.CaptureLocalState(),Is.EqualTo(before));}
  [Test] public void FinalHpBatchSavesBothTargetsOnceAndRepeatDoesNotSave(){int saves=0;string stored=null;var d=new CombatSceneDriver(Fresh,()=>null,(m,r)=>{saves++;stored=m.CaptureLocalState();return r+1;},()=>true);d.Open();var finals=new Dictionary<string,int>{{"gun-a",1500},{"gun-b",2000}};ApplyBatch(d,finals);Assert.That(saves,Is.EqualTo(2));Assert.That(d.StateJson,Is.EqualTo(stored));var restored=BasicCombatSimulation.RestoreLocalState(stored,Fresh);Assert.That(restored.GetHp("gun-a"),Is.EqualTo(1500));Assert.That(restored.GetHp("gun-b"),Is.EqualTo(2000));ApplyBatch(d,finals);Assert.That(saves,Is.EqualTo(2));}
  [Test] public void FinalHpBatchSaveFailureKeepsBothLiveTargetsAndRequiresRecovery(){bool fail=false;var d=new CombatSceneDriver(Fresh,()=>null,(m,r)=>fail?throw new InvalidOperationException("TEST_ONLY save failure"):r+1,()=>true);d.Open();var before=d.StateJson;fail=true;Assert.Throws<InvalidOperationException>(()=>ApplyBatch(d,new Dictionary<string,int>{{"gun-a",1500},{"gun-b",2000}}));Assert.That(d.StateJson,Is.EqualTo(before));Assert.That(d.RecoveryRequired,Is.True);}
  [Test] public void FinalHpBatchPreservesOtherSavedStateAndRoundTripAnchors(){var s=Fresh();var state=JObject.Parse(s.CaptureLocalState());foreach(var id in new[]{"gun-a","gun-b"}){var v=((JArray)state["actors"]).Single(a=>(string)a["id"]==id)["vitals"];v["hp"]=333;v["anchorHp"]=333;}s=BasicCombatSimulation.RestoreLocalState(state.ToString(),Fresh);s.ApplyResolvedShield("gun-a",new CombatShieldSource("train","fixture",0),2000,100);s.SetPaused(true);var before=JObject.Parse(s.CaptureLocalState());ApplyBatch(s,new Dictionary<string,int>{{"gun-a",1500},{"gun-b",2000}});Assert.That(s.GetHp("gun-a"),Is.EqualTo(499));Assert.That(s.GetHp("gun-b"),Is.EqualTo(666));var after=JObject.Parse(s.CaptureLocalState());foreach(var id in new[]{"gun-a","gun-b"}){var old=((JArray)before["actors"]).Single(a=>(string)a["id"]==id)["vitals"];var next=((JArray)after["actors"]).Single(a=>(string)a["id"]==id)["vitals"];next["hp"]=old["hp"];next["maxHp"]=old["maxHp"];}Assert.That(JToken.DeepEquals(before,after),Is.True);s=BasicCombatSimulation.RestoreLocalState(s.CaptureLocalState(),Fresh);ApplyBatch(s,new Dictionary<string,int>{{"gun-a",1000},{"gun-b",1000}});Assert.That(s.GetHp("gun-a"),Is.EqualTo(333));Assert.That(s.GetHp("gun-b"),Is.EqualTo(333));}
  [Test] public void ExistingModelOwnsEffectiveHpAndKeepsSameTypeTurretsIndependent(){var s=Fresh();s.ApplyResolvedMaxHp("gun-a",1500);Assert.AreEqual(1500,s.GetHp("gun-a"));Assert.AreEqual(1000,s.GetHp("gun-b"));Assert.AreEqual(1500,(int)HpRow(s,"gun-a")["maxHp"]);Assert.AreEqual(1000,(int)HpRow(s,"gun-b")["maxHp"]);Assert.AreEqual(1500,(int)HpRow(BasicCombatSimulation.RestoreLocalState(s.CaptureLocalState(),Fresh),"gun-a")["maxHp"]);}
  [Test] public void RestoreReplaysActualAttackAndResolvedRepairIdentically(){var s=Fresh();s.ApplyResolvedMaxHp("train",1500);var copy=BasicCombatSimulation.RestoreLocalState(s.CaptureLocalState(),Fresh);s.Advance(100000000,200);copy.Advance(100000000,200);Assert.AreEqual(s.CaptureLocalState(),copy.CaptureLocalState());Assert.Greater(s.Events.Count,0);Assert.AreEqual(s.ApplyResolvedRepair("train",99,10000),copy.ApplyResolvedRepair("train",99,10000));s.ApplyResolvedMaxHp("train",1000);copy.ApplyResolvedMaxHp("train",1000);Assert.AreEqual(s.CaptureLocalState(),copy.CaptureLocalState());Assert.AreEqual(1000,(int)s.ReadHudState()["trainMaxHp"]);}
  [Test] public void RepeatedFinalStatIsIdempotentAndDoesNotPublishHealOrDamage(){var s=Fresh();s.ApplyResolvedMaxHp("train",1500);var saved=s.CaptureLocalState();s.ApplyResolvedMaxHp("train",1500);Assert.AreEqual(saved,s.CaptureLocalState());Assert.AreEqual(0,s.Events.Count);Assert.AreEqual(0,((JArray)s.ReadHudState()["effectResults"]).Count);}
  [Test] public void DriverPublishesOnlySavedRebaseAndPreservesLiveStateOnSaveFailure(){bool fail=false;var d=new CombatSceneDriver(Fresh,()=>null,(m,r)=>fail?throw new InvalidOperationException("TEST_ONLY save failure"):r+1,()=>true);d.Open();var method=typeof(CombatSceneDriver).GetMethod("ApplyResolvedMaxHp");Assert.NotNull(method,"Resolved final stat is not connected to existing saved-transition owner");method.Invoke(d,new object[]{"gun-a",1500});var before=d.StateJson;fail=true;Assert.Throws<System.Reflection.TargetInvocationException>(()=>method.Invoke(d,new object[]{"gun-a",2000}));Assert.AreEqual(before,d.StateJson);Assert.IsTrue(d.RecoveryRequired);}
  static BasicCombatSimulation SkillFresh(){var t=(JObject)JObject.Parse(System.IO.File.ReadAllText("D:/Project/LASTRAIL/Worktrees/11ec/LASTRAIL/attendance-pass-20260907/server/audit-results/ce03-local-producer/draft.json"))["draft"]["template"];var actors=((JArray)t["operators"]).Select((x,i)=>Actor((string)x["operatorId"],false,false,i)).Concat(new[]{Actor("train",false,true,5)}).ToArray();var enemy=new BasicCombatActor("enemy",true,false,false,0,100000,2000,0,1000,1,0,BasicCombatTarget.Operators,4000);var model=new BasicCombatSimulation("TEST_ONLY_vitals_recovery",500000,1,actors,new[]{new[]{enemy}},true);model.ConfigureSkills(t,"op_reina",50);return model;}
  static BasicCombatSimulation ChargedFresh(){var s=SkillFresh();s.ConfigureLocalLeaderCharge(4);return s;}
  [Test] public void FinalHpBatchPreservesSavedChargeCooldownAndQueuedAction(){var s=ChargedFresh();var seeded=JObject.Parse(s.CaptureLocalState());seeded["leaderCharge"]=37;((JArray)seeded["skillReady"])[0]["ready"]=100;s=BasicCombatSimulation.RestoreLocalState(seeded.ToString(),ChargedFresh);Assert.That(s.RequestSkill("batch-queued","op_reina","op_reina.active"),Is.EqualTo("QUEUED"));s.SetPaused(true);var before=JObject.Parse(s.CaptureLocalState());ApplyBatch(s,new Dictionary<string,int>{{"op_kyle",1500},{"op_reina",2000}});var after=JObject.Parse(s.CaptureLocalState());foreach(var field in new[]{"leaderCharge","skillReady","commands","attacks","statuses","clock","effectJournal"})Assert.That(JToken.DeepEquals(before[field],after[field]),Is.True,field);var restored=BasicCombatSimulation.RestoreLocalState(s.CaptureLocalState(),ChargedFresh);Assert.That(restored.CaptureLocalState(),Is.EqualTo(s.CaptureLocalState()));}
  [Test] public void UnsupportedResolvedMaxCannotInvalidateScheduledRecovery(){var s=SkillFresh();var before=s.CaptureLocalState();Assert.Throws<ArgumentException>(()=>s.ApplyResolvedMaxHp("op_kyle",1));Assert.AreEqual(before,s.CaptureLocalState());}
  [Test] public void DownRebasePreservesDeadlineAndRestoresOriginalRecoveryRatio(){var s=SkillFresh();for(int i=0;i<20&&s.GetHp("op_kyle")>0;i++)s.Advance(500000,1);Assert.AreEqual(0,s.GetHp("op_kyle"));var row=((JArray)JObject.Parse(s.CaptureLocalState())["actors"]).Single(a=>(string)a["id"]=="op_kyle");var due=(long)row["recoverAt"];s.ApplyResolvedMaxHp("op_kyle",1500);Assert.AreEqual(0,s.GetHp("op_kyle"));var copy=BasicCombatSimulation.RestoreLocalState(s.CaptureLocalState(),SkillFresh);while(s.Tick<due){s.Advance(500000,1);copy.Advance(500000,1);}Assert.Greater(s.GetHp("op_kyle"),0);Assert.AreEqual(s.CaptureLocalState(),copy.CaptureLocalState());s.ApplyResolvedMaxHp("op_kyle",1000);Assert.AreEqual(s.GetHp("op_kyle")*1500/1000,copy.GetHp("op_kyle"));}
  [Test] public void LowestRatioTargetUsesEffectiveMaximum(){var s=SkillFresh();var state=JObject.Parse(s.CaptureLocalState());foreach(var pair in new[]{("op_kyle",333),("op_reina",400)}){var v=((JArray)state["actors"]).Single(a=>(string)a["id"]==pair.Item1)["vitals"];v["hp"]=pair.Item2;v["anchorHp"]=pair.Item2;}s=BasicCombatSimulation.RestoreLocalState(state.ToString(),SkillFresh);s.ApplyResolvedMaxHp("op_kyle",1500);var flags=System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic;var allies=(System.Collections.IEnumerable)typeof(BasicCombatSimulation).GetField("allies",flags).GetValue(s);var caster=allies.Cast<object>().First();var targets=(Array)typeof(BasicCombatSimulation).GetMethod("SkillTargets",flags).Invoke(s,new object[]{caster,"ally_lowest_hp"});var cfg=(BasicCombatActor)targets.GetValue(0).GetType().GetField("Config",flags).GetValue(targets.GetValue(0));Assert.AreEqual("op_kyle",cfg.Id);}
  [Test] public void RestoreCannotBypassOriginalRecoveryBounds(){var s=SkillFresh();var j=JObject.Parse(s.CaptureLocalState());var v=((JArray)j["actors"]).Single(a=>(string)a["id"]=="op_kyle")["vitals"];v["maxHp"]=1;v["hp"]=1;Assert.Throws<ArgumentException>(()=>BasicCombatSimulation.RestoreLocalState(j.ToString(),SkillFresh));}
  [Test] public void BadSavedAnchorDoesNotChangeLiveState(){var s=Fresh();s.ApplyResolvedMaxHp("gun-a",1500);var raw=s.CaptureLocalState();var j=JObject.Parse(raw);((JArray)j["actors"])[1]["vitals"]["anchorMaxHp"]=0;Assert.Throws<ArgumentException>(()=>BasicCombatSimulation.RestoreLocalState(j.ToString(),Fresh));Assert.AreEqual(raw,s.CaptureLocalState());}
 }
}
